import SwiftUI

// MARK: - 1. 数据模型
struct User: Codable, Identifiable, Hashable {
    let id: Int
    let name: String
    let email: String
}

// MARK: - 2. 错误类型
enum NetworkError: LocalizedError {
    case invalidURL
    case decodingFailed

    var errorDescription: String? {
        switch self {
        case .invalidURL:      return "URL 不合法"
        case .decodingFailed:  return "数据解析失败"
        }
    }
}

// MARK: - 3. 单个请求：async/await
func fetchUser(id: Int) async throws -> User {
    guard let url = URL(string: "https://jsonplaceholder.typicode.com/users/\(id)") else {
        throw NetworkError.invalidURL
    }
    // URLSession.data(from:) 是原生异步 API，会随 Task 取消而取消
    let (data, response) = try await URLSession.shared.data(from: url)
    guard let http = response as? HTTPURLResponse, (200...299).contains(http.statusCode) else {
        throw NetworkError.invalidURL
    }
    do {
        return try JSONDecoder().decode(User.self, from: data)
    } catch {
        throw NetworkError.decodingFailed
    }
}

// MARK: - 4. 并发请求：withThrowingTaskGroup
// 子任务返回 (原始id, 结果)，这样才能还原顺序
func fetchUsers(ids: [Int]) async throws -> [User] {
    try await withThrowingTaskGroup(of: (Int, User).self) { group in
        for id in ids {
            // 闭包内必须 await，返回值类型才是 (Int, User)
            group.addTask {
                try Task.checkCancellation()   // 协作式取消检查
                let user = try await fetchUser(id: id)
                return (id, user)
            }
        }

        var buffer: [Int: User] = [:]
        for try await (id, user) in group {
            buffer[id] = user                  // 谁先完成谁先写入，顺序不确定
        }
        return ids.compactMap { buffer[$0] }   // 按传入顺序还原
    }
}

// MARK: - 5. ViewModel（主线程安全）
@MainActor
final class UsersViewModel: ObservableObject {
    @Published var users: [User] = []
    @Published var isLoading = false
    @Published var errorMessage: String?

    func load(ids: [Int]) async {
        isLoading = true
        errorMessage = nil
        do {
            // await 的结果回来时已在 MainActor，可直接改 @Published
            users = try await fetchUsers(ids: ids)
        } catch is CancellationError {
            // 页面已消失，静默处理
        } catch {
            errorMessage = error.localizedDescription
        }
        isLoading = false
    }
}

// MARK: - 6. SwiftUI 视图
struct UsersView: View {
    @StateObject private var viewModel = UsersViewModel()

    var body: some View {
        NavigationStack {
            Group {
                if viewModel.isLoading {
                    ProgressView("加载中…")
                } else if let msg = viewModel.errorMessage {
                    Text(msg).foregroundStyle(.red)
                } else {
                    List(viewModel.users) { user in
                        VStack(alignment: .leading, spacing: 4) {
                            Text(user.name).font(.headline)
                            Text(user.email).font(.subheadline).foregroundStyle(.secondary)
                        }
                    }
                }
            }
            .navigationTitle("用户列表")
        }
        // .task 随视图出现启动、消失自动取消，无需手动管理 Task
        .task {
            await viewModel.load(ids: [1, 2, 3, 4, 5])
        }
    }
}

